def _doc_text(path):
    from docx import Document
    doc = Document(str(path))
    chunks = [p.text for p in doc.paragraphs]
    for table in doc.tables:
        chunks.extend(cell.text for row in table.rows for cell in row.cells)
    return "\n".join(chunks)

def recon_status(ws):
    with sqlite3.connect(_db(ws)) as con:
        row = con.execute("SELECT resolution_status, resolution_note FROM crm_revenue_reconciliation WHERE recon_id=?", (TARGET_RECON,)).fetchone()
    if row is None:
