    status, note = row
    note_text = _norm(note)
    has_timing = any(token in note_text for token in ("跨期间", "跨期", "crossperiod", "timing"))
    has_pending = any(token in note_text for token in ("尚未完成", "待复核", "未完成", "未解决", "继续复核", "inreview", "review"))
    ok = status == "IN_REVIEW" and has_timing and has_pending
    return {"score": int(ok), "detail": f"status={status!r}, note={note!r}"}

def memo_written(ws):
    path = Path(ws) / TARGET_MEMO
    if not path.exists() or path.suffix.lower() != ".docx":
        return {"score": 0, "detail": f"missing {TARGET_MEMO}"}
    try:
        text = _doc_text(path)
    except Exception as exc:
        return {"score": 0, "detail": f"cannot read memo: {exc}"}
    compact = _norm(text)
    required = ["1100000", "1000000", "800000", "recon-24017", "opp-cohort-1001", "fy2024-q1", "fy2024-q2", "sf-ac-0700", "in_review"]
    missing = [value for value in required if _norm(value) not in compact]
    # Accept the same signed correction expressed in cents or in dollars.
    signed_correction_ok = "-200000" in compact or bool(re.search(r"-\s*(?:usd|\$)?\s*2,?000(?:\b|[^\d])", text, re.IGNORECASE))
    if not signed_correction_ok:
        missing.append("-200000 or -USD 2,000")
    # Keep the comma-bearing legal-name variant check separate because _norm removes punctuation.
    name_ok = "acmeinc" in compact and "acme,inc" in text.lower().replace(" ", "")
    if not name_ok:
        missing.append("Acme, Inc")
